'use strict';
const ZOOZI_NOVEL={"id":"princess-al-zahraa-in-wonderland","title":"Princess AL Zahraa in Wonderland","series":"Novels","color":"#ad3973","tint":"#ffe9f1","coverRatio":0.6666666666666666,"imageRatio":0.6666666666666666,"pdf":"Princess_AL_Zahraa_in_Wonderland.pdf","isNovel":true,"cover":"data:image/webp;base64,","pages":[null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null],"loaded":false};

let novelUtterance=null,novelSpeechTimer=null,novelVoiceURI='',novelTextOpen=false;
try{novelVoiceURI=localStorage.getItem('zoozi-novel-voice')||'';}catch{}
function findStory(id){return id===ZOOZI_NOVEL.id?ZOOZI_NOVEL:STORIES.find(s=>s.id===id);}
function novelsShelf(){
  const b=ZOOZI_NOVEL;
  return `<section class="series novel-final-section" id="novels"><div class="series-heading" style="--series-color:#ad3973;--series-tint:#ffe9f1"><span class="series-number" aria-hidden="true">8</span><h2>Novels</h2></div><div class="books"><button class="book-card" data-story="${b.id}" style="--book-color:${b.color};--book-tint:${b.tint}" aria-label="Read ${b.title}"><div class="novel-book-cover"><img src="${b.cover}" alt="${b.title}" loading="lazy"></div><div class="book-copy"><h3>${b.title}</h3><div class="book-meta"><span>${b.pages.length} pages</span><span class="book-listen">${speaker}<span>Read & listen</span></span></div></div></button></div></section>`;
}
function novelsLibrary(){
  resetForOnline();document.title='Novels · Zoozi App';
  app.innerHTML=`<div class="library novels-library"><div class="reader-top"><button class="back-button" id="back-library">Library</button><h1 class="reader-title">Novels</h1></div><p class="novels-intro">A little wonder. A brave heart. A story to treasure.</p>${novelsShelf()}</div>`;
  $('#back-library').onclick=()=>navigate();app.querySelector('[data-story]').onclick=()=>navigate(ZOOZI_NOVEL.id,0);window.scrollTo({top:0,behavior:'instant'});
}
function novelPageMarkup(){
  const p=current.pages[pageIndex];
  return `<div class="novel-page-picture"><img src="${p.image}" alt="Illustrated page ${pageIndex+1} of ${escapeHTML(current.title)}" width="1440" height="2160" draggable="false" decoding="async"><button class="novel-zoom-button" id="novel-zoom" aria-label="Enlarge illustrated page">Zoom</button></div><section class="reading novel-reading"><div class="sentences"><p>Read with me</p><small>One tap reads on and turns the pages.</small></div><button class="listen" data-listen="en" aria-label="Read this story with automatic page turns" aria-pressed="false">${speaker}<span>Read story</span></button></section><div class="novel-tools"><label>Go to page <select id="novel-page-select">${current.pages.map((_,i)=>`<option value="${i}" ${i===pageIndex?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Reading voice <select id="novel-voice"><option value="">Default English voice</option></select></label></div><details class="novel-transcript" id="novel-text" ${novelTextOpen?'open':''}><summary>Read the text</summary><div lang="en">${p.en.map((text,i)=>`<p data-novel-paragraph="${i}">${escapeHTML(text)}</p>`).join('')}</div></details><p class="novel-voice-note">Narration uses your device's English voice. Choose a voice above if available.</p><div class="page-footnote"><span>Zoozi App</span><span>${pageIndex+1} / ${current.pages.length}</span></div>`;
}
function englishNovelVoices(){return window.speechSynthesis?window.speechSynthesis.getVoices().filter(v=>/^en(?:[-_]|$)/i.test(v.lang)):[];}
function fillNovelVoices(){
  const select=$('#novel-voice');if(!select)return;
  select.innerHTML='<option value="">Default English voice</option>'+englishNovelVoices().map(v=>`<option value="${escapeHTML(v.voiceURI)}">${escapeHTML(v.name)} (${escapeHTML(v.lang)})</option>`).join('');
  select.value=novelVoiceURI;if(select.selectedIndex<0)select.value='';
}
function bindNovelPage(){
  if(!current?.isNovel)return;
  fillNovelVoices();
  $('#novel-page-select').onchange=e=>void flip(Number(e.target.value)-pageIndex);
  $('#novel-voice').onchange=e=>{novelVoiceURI=e.target.value;try{localStorage.setItem('zoozi-novel-voice',novelVoiceURI);}catch{}};
  $('#novel-text').ontoggle=e=>{novelTextOpen=e.target.open;};
  const zoom=$('#page-zoom'),image=$('#zoom-image');
  image.src=current.pages[pageIndex].image;image.alt=`Page ${pageIndex+1} of ${current.title}`;
  $('#novel-zoom').onclick=()=>{if(!zoom.open)zoom.showModal();};
}
function stopNovelSpeech(){
  clearTimeout(novelSpeechTimer);novelSpeechTimer=null;
  if(novelUtterance){novelUtterance.onstart=null;novelUtterance.onend=null;novelUtterance.onerror=null;novelUtterance=null;window.speechSynthesis?.cancel();}
  app.querySelectorAll('[data-novel-paragraph]').forEach(p=>p.classList.remove('is-reading'));
}
function novelSpeechChunks(paragraphs){
  const chunks=[];
  paragraphs.forEach((paragraph,index)=>{
    const sentences=paragraph.match(/[^.!?]+(?:[.!?]+["'”’]?|$)/g)||[paragraph];
    for(let sentence of sentences){
      sentence=sentence.trim();
      while(sentence.length>180){let cut=sentence.lastIndexOf(' ',180);if(cut<1)cut=180;chunks.push({text:sentence.slice(0,cut),paragraph:index});sentence=sentence.slice(cut).trim();}
      if(sentence)chunks.push({text:sentence,paragraph:index});
    }
  });
  return chunks;
}
function playNovelPage(session){
  if(!window.speechSynthesis||typeof SpeechSynthesisUtterance==='undefined'){stopAudio();notify('Read-aloud is not available in this browser. Try Chrome or Safari with an English voice installed.');return;}
  const synth=window.speechSynthesis,story=current,index=pageIndex,attempt=++playAttempt;
  const chunks=novelSpeechChunks(story.pages[index].en);let next=0;
  const valid=()=>readingStory&&session===readSession&&attempt===playAttempt&&current===story&&pageIndex===index&&!document.hidden;
  function failed(message){if(!valid())return;stopAudio();notify(message);}
  function speakNext(){
    if(!valid())return;
    if(next>=chunks.length){
      novelUtterance=null;
      if(index===story.pages.length-1){stopAudio();storyFinished=true;syncReadButton();notify('The end! Tap Read again to hear the story again.');}
      else void flip(1);
      return;
    }
    const chunk=chunks[next++],utterance=new SpeechSynthesisUtterance(chunk.text);
    const voices=englishNovelVoices();
    const voice=voices.find(v=>v.voiceURI===novelVoiceURI)||voices.find(v=>/Samantha|Aria|Jenny|Google UK English Female|Microsoft Ana/i.test(v.name))||voices.find(v=>v.default)||voices[0];
    if(voice)utterance.voice=voice;
    utterance.lang=voice?.lang||'en-US';utterance.rate=.92*prefs.speed;utterance.pitch=1;utterance.volume=1;
    novelUtterance=utterance;
    utterance.onstart=()=>{
      clearTimeout(novelSpeechTimer);novelSpeechTimer=null;
      if(!valid())return;
      app.querySelectorAll('[data-novel-paragraph]').forEach(p=>p.classList.toggle('is-reading',Number(p.dataset.novelParagraph)===chunk.paragraph));
    };
    utterance.onend=()=>{clearTimeout(novelSpeechTimer);novelSpeechTimer=null;if(valid()&&novelUtterance===utterance){novelUtterance=null;speakNext();}};
    utterance.onerror=()=>failed('Narration could not continue. Choose an English voice, then tap Read story to retry this page.');
    novelSpeechTimer=setTimeout(()=>failed('Your device did not start its reading voice. Choose an English voice, then tap Read story again.'),12000);
    try{synth.speak(utterance);}catch{failed('Narration could not start. Open this app in Chrome or Safari and try again.');}
  }
  syncReadButton();startMusic(true);setMusicLevel();speakNext();
}
window.addEventListener('DOMContentLoaded',()=>{if(window.speechSynthesis)window.speechSynthesis.addEventListener('voiceschanged',fillNovelVoices);});

let novelDataRequest=null;
function loadNovelData(){
  if(ZOOZI_NOVEL.loaded)return Promise.resolve();
  if(novelDataRequest)return novelDataRequest;
  novelDataRequest=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='novel-pages.js?v=12';
    script.onload=()=>{script.remove();ZOOZI_NOVEL.loaded?resolve():reject(new Error('The book did not load.'));};
    script.onerror=()=>{script.remove();reject(new Error('The book download failed.'));};
    document.head.appendChild(script);
  }).catch(error=>{novelDataRequest=null;throw error;});
  return novelDataRequest;
}
async function loadNovelForRoute(route){
  ++turnToken;turning=false;stopAudio();pauseMusic();current=null;
  app.innerHTML='<div class="library"><button class="back-button" id="novel-loading-back">Library</button><section class="startup-message" role="status"><h1>Opening your storybook...</h1><p>Downloading the illustrated pages. The first visit may take a moment.</p></section></div>';
  $('#novel-loading-back').onclick=()=>navigate();
  try{await loadNovelData();if(location.hash===route)parseRoute();}
  catch{if(location.hash!==route)return;app.innerHTML='<div class="library"><button class="back-button" id="novel-loading-back">Library</button><section class="startup-message" role="status"><h1>Let’s try again</h1><p>Check your internet connection, then reopen the storybook.</p><button class="primary-button" id="novel-retry">Try again</button></section></div>';$('#novel-loading-back').onclick=()=>navigate();$('#novel-retry').onclick=()=>void loadNovelForRoute(route);}
}
